-- -----------------------------------
-- Table structure for `sites_details`
-- -----------------------------------

DROP TABLE IF EXISTS `sites_details`;
CREATE TABLE `sites_details` (
  `id` int(6) NOT NULL AUTO_INCREMENT,
  `site_id` int(10) DEFAULT NULL,
  `project` int(10) DEFAULT NULL,
  `routebrand` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `router_id` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `simnumber` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `simowner` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `status` tinyint(1) DEFAULT NULL,
  `created_at` varchar(20) CHARACTER SET utf8 NOT NULL,
  `closedDate` varchar(60) CHARACTER SET utf8 DEFAULT NULL,
  `statusType` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `statusDate` datetime DEFAULT NULL,
  `unique_id` varchar(50) CHARACTER SET utf8 NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=7676 DEFAULT CHARSET=latin1;

